-- PostgreSQL schema for the ported core.  Names use snake_case so queries are portable.
CREATE TABLE users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  login VARCHAR(15) NOT NULL UNIQUE,
  password VARCHAR(60) NOT NULL,
  email VARCHAR(50) NOT NULL UNIQUE,
  game_pass VARCHAR(8) NOT NULL,
  game_ip BIGINT NOT NULL,
  real_ip BIGINT NOT NULL DEFAULT 0,
  home_ip BIGINT NOT NULL DEFAULT 0,
  learning BOOLEAN NOT NULL DEFAULT FALSE,
  premium BOOLEAN NOT NULL DEFAULT FALSE,
  last_login TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE users_stats (
  uid BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  date_joined TIMESTAMPTZ NOT NULL DEFAULT now(), exp BIGINT NOT NULL DEFAULT 0,
  certifications VARCHAR(30) NOT NULL DEFAULT '', awards VARCHAR(50) NOT NULL DEFAULT '',
  time_playing REAL NOT NULL DEFAULT 0, mission_count INTEGER NOT NULL DEFAULT 0,
  hack_count INTEGER NOT NULL DEFAULT 0, ddos_count INTEGER NOT NULL DEFAULT 0,
  money_earned BIGINT NOT NULL DEFAULT 0, money_transfered BIGINT NOT NULL DEFAULT 0,
  money_hardware BIGINT NOT NULL DEFAULT 0, money_research BIGINT NOT NULL DEFAULT 0,
  profile_views INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE hardware (server_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name VARCHAR(15) NOT NULL, cpu REAL NOT NULL DEFAULT 500, hdd REAL NOT NULL DEFAULT 100, ram REAL NOT NULL DEFAULT 256, net REAL NOT NULL DEFAULT 1, is_npc BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE software (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, soft_name VARCHAR(25) NOT NULL, soft_version INTEGER NOT NULL, soft_size INTEGER NOT NULL, soft_ram INTEGER NOT NULL, soft_type SMALLINT NOT NULL, soft_hidden BOOLEAN NOT NULL DEFAULT FALSE, is_npc BOOLEAN NOT NULL DEFAULT FALSE, is_folder BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE bank_accounts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, bank_acc BIGINT NOT NULL UNIQUE, bank_pass VARCHAR(6) NOT NULL, bank_id BIGINT NOT NULL, bank_user BIGINT NOT NULL REFERENCES users(id), cash BIGINT NOT NULL DEFAULT 0, date_created TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE mails (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sender_id BIGINT NOT NULL, recipient_id BIGINT NOT NULL REFERENCES users(id), type SMALLINT NOT NULL DEFAULT 0, subject VARCHAR(40) NOT NULL, text TEXT NOT NULL, date_sent TIMESTAMPTZ NOT NULL DEFAULT now(), is_read BOOLEAN NOT NULL DEFAULT FALSE, is_deleted BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE processes (pid BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, creator_id BIGINT NOT NULL REFERENCES users(id), victim_id BIGINT NOT NULL DEFAULT 0, action SMALLINT NOT NULL, soft_id BIGINT NOT NULL DEFAULT 0, info VARCHAR(30) NOT NULL DEFAULT '', info_str TEXT NOT NULL DEFAULT '', time_start TIMESTAMPTZ NOT NULL DEFAULT now(), time_end TIMESTAMPTZ NOT NULL DEFAULT now(), time_ideal INTEGER NOT NULL DEFAULT 0, time_worked INTEGER NOT NULL DEFAULT 0, is_paused BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE processes_paused (pid BIGINT PRIMARY KEY REFERENCES processes(pid) ON DELETE CASCADE, time_left INTEGER NOT NULL, user_id BIGINT NOT NULL REFERENCES users(id), time_paused TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE missions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, type SMALLINT NOT NULL, status SMALLINT NOT NULL, hirer BIGINT NOT NULL, victim BIGINT NOT NULL, info BIGINT NOT NULL DEFAULT 0, info2 BIGINT NOT NULL DEFAULT 0, prize BIGINT NOT NULL DEFAULT 0, user_id BIGINT REFERENCES users(id), level SMALLINT NOT NULL, date_generated TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ranking_user (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, rank INTEGER NOT NULL);
CREATE TABLE friend_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, requested_by BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, UNIQUE(user_id, requested_by));
CREATE TABLE users_friends (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, friend_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, date_add TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id, friend_id));
CREATE TABLE certifications (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, cert_level SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE users_puzzle (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, puzzle_id BIGINT NOT NULL DEFAULT 0);
CREATE TABLE users_learning (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, learning BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE users_language (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, lang VARCHAR(2) NOT NULL DEFAULT 'en');
CREATE TABLE cache (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, reputation BIGINT NOT NULL DEFAULT 0);
CREATE TABLE cache_profile (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, expire_date TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), text TEXT NOT NULL, is_npc BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE log_edit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, vic_id BIGINT NOT NULL, is_npc BOOLEAN NOT NULL DEFAULT FALSE, editor_id BIGINT NOT NULL);
